from pathlib import Path

ROOT=Path(__file__).resolve().parent
project=ROOT
while project != project.parent and not (project/'www'/'index.html').exists():
    project=project.parent
if not (project/'www'/'index.html').exists():
    raise SystemExit('ERRO: não encontrei a pasta www do Smart Talles. Coloque esta pasta na raiz do projeto e execute novamente.')
idx,app,css=[project/'www'/x for x in ('index.html','app.js','style.css')]
I,A,C=[p.read_text(encoding='utf-8') for p in (idx,app,css)]
marker='SMART-TALLES-ACCESSORY-SEARCH-V1'
if marker in I or marker in A or marker in C:
    print('A pesquisa de acessórios já está instalada. Nenhuma alteração foi feita.')
    raise SystemExit(0)

launcher='''</div>\n     <div id="accessorySearchLauncher" class="accessory-search-launcher hidden">\n       <button id="openAccessorySearch" class="secondary accessory-search-button" type="button">🔎 Pesquisar acessórios</button>\n       <small>Pesquise pelo nome, modelo, marca ou compatibilidade.</small>\n     </div>\n     <div id="accessoryPreview"'''
needle='</div>\n     <div id="accessoryPreview"'
if needle in I:
    I=I.replace(needle,launcher,1)
else:
    raise SystemExit('ERRO: não encontrei a área de seleção do produto no index.html.')

modal='''\n<!-- SMART-TALLES-ACCESSORY-SEARCH-V1 -->\n<div id="accessorySearchModal" class="accessory-modal" aria-hidden="true">\n  <div class="accessory-modal-backdrop" data-accessory-close></div>\n  <div class="accessory-modal-dialog" role="dialog" aria-modal="true" aria-labelledby="accessorySearchTitle">\n    <div class="accessory-modal-head">\n      <div><span class="eyebrow">CATÁLOGO DE ACESSÓRIOS</span><h2 id="accessorySearchTitle">Pesquisar acessórios</h2><p>Digite e filtre instantaneamente os produtos.</p></div>\n      <button id="closeAccessorySearch" class="accessory-modal-close" type="button" aria-label="Fechar">×</button>\n    </div>\n    <div class="accessory-search-box"><span>🔎</span><input id="accessorySearchInput" type="search" autocomplete="off" placeholder="Digite nome, modelo, marca ou compatibilidade..." aria-label="Pesquisar acessórios"></div>\n    <div id="accessorySearchCount" class="accessory-search-count"></div>\n    <div id="accessorySearchResults" class="accessory-search-results"></div>\n  </div>\n</div>\n'''
I=I.replace('</body>',modal+'</body>',1)

js='''\n/* SMART-TALLES-ACCESSORY-SEARCH-V1 */\n(function(){\n  const launcher=document.getElementById('accessorySearchLauncher');\n  const openBtn=document.getElementById('openAccessorySearch');\n  const modal=document.getElementById('accessorySearchModal');\n  const closeBtn=document.getElementById('closeAccessorySearch');\n  const input=document.getElementById('accessorySearchInput');\n  const results=document.getElementById('accessorySearchResults');\n  const count=document.getElementById('accessorySearchCount');\n  if(!launcher||!openBtn||!modal||!closeBtn||!input||!results)return;\n  const text=v=>String(v??'').toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'');\n  const productSearchText=p=>[p.model,p.brand,p.sku,p.category,p.compatibility,p.compatibilities,p.compatible,p.compatible_with,p.description,p.name,p.title].flatMap(v=>Array.isArray(v)?v:[v]).join(' ');\n  const accessories=()=>products.filter(p=>text(p.category||'').includes('acessor'));\n  function open(){modal.classList.add('open');modal.setAttribute('aria-hidden','false');document.body.classList.add('accessory-modal-open');input.value='';render('');setTimeout(()=>input.focus(),50)}\n  function close(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true');document.body.classList.remove('accessory-modal-open')}\n  function add(id){const x=products.find(p=>Number(p.id)===Number(id));if(!x)return;if(Number(x.price)<=0){alert('Este produto ainda está sem preço cadastrado. Abra Administração e informe o preço antes de adicionar ao orçamento.');return}cart.push({...x});renderCart();close();document.getElementById('nova-venda')?.scrollIntoView({behavior:'smooth',block:'start'})}\n  window.addAccessoryFromSearch=add;\n  function render(query){const q=text(query);const arr=accessories().filter(p=>!q||text(productSearchText(p)).includes(q));count.textContent=arr.length+' '+(arr.length===1?'acessório encontrado':'acessórios encontrados');if(!arr.length){results.innerHTML='<div class="accessory-search-empty"><span>🔎</span><b>Nenhum acessório encontrado</b><small>Tente outro nome, modelo, marca ou compatibilidade.</small></div>';return}results.innerHTML=arr.map(p=>{const img=p.image?`<img src="${esc(p.image)}" alt="${esc(p.model||'Acessório')}" loading="lazy">`:'<div class="accessory-search-noimage">🛍️</div>';const sku=p.sku?`<small>SKU: ${esc(p.sku)}</small>`:'';const brandLine=p.brand?`<span>${esc(p.brand)}</span>`:'';const priceText=Number(p.price)>0?money(p.price):'Preço não cadastrado';return `<article class="accessory-search-card"><div class="accessory-search-photo">${img}</div><div class="accessory-search-info"><div class="accessory-search-brand">${brandLine}</div><h3>${esc(p.model||p.name||'Acessório')}</h3>${sku}<strong>${priceText}</strong><button type="button" class="primary accessory-add-button" onclick="addAccessoryFromSearch(${Number(p.id)})">＋ Adicionar ao orçamento</button></div></article>`}).join('')}\n  function sync(){launcher.classList.toggle('hidden',currentCategory!=='Acessórios')}\n  openBtn.addEventListener('click',open);closeBtn.addEventListener('click',close);input.addEventListener('input',()=>render(input.value));modal.addEventListener('click',e=>{if(e.target.hasAttribute('data-accessory-close'))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal.classList.contains('open'))close()});\n  const oldSetCategory=window.setCategory;window.setCategory=function(cat){const r=oldSetCategory?oldSetCategory(cat):undefined;sync();return r};sync();\n})();\n'''
A=A.replace('// Painel lateral de clima e qualidade do ar — Floriano/PI',js+'\n// Painel lateral de clima e qualidade do ar — Floriano/PI',1)

C+='''\n/* SMART-TALLES-ACCESSORY-SEARCH-V1 */\n.accessory-search-launcher{display:flex;align-items:center;gap:12px;margin:14px 0 4px}.accessory-search-launcher.hidden{display:none}.accessory-search-launcher small{color:var(--muted)}.accessory-search-button{min-height:44px}.accessory-modal{position:fixed;inset:0;z-index:9999;display:none;align-items:center;justify-content:center;padding:18px}.accessory-modal.open{display:flex}.accessory-modal-backdrop{position:absolute;inset:0;background:rgba(4,15,29,.68);backdrop-filter:blur(3px)}.accessory-modal-dialog{position:relative;width:min(980px,100%);max-height:min(88vh,820px);overflow:hidden;background:#fff;border-radius:22px;box-shadow:0 30px 90px rgba(0,0,0,.28);display:flex;flex-direction:column}.accessory-modal-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;padding:22px 24px 14px;border-bottom:1px solid var(--line)}.accessory-modal-head h2{margin:4px 0 2px}.accessory-modal-head p{margin:0;color:var(--muted)}.accessory-modal-close{width:42px;height:42px;border:0;border-radius:12px;background:#f1f4f8;font-size:28px;cursor:pointer;line-height:1}.accessory-search-box{display:flex;align-items:center;gap:10px;margin:16px 24px 8px;padding:0 15px;border:2px solid var(--line);border-radius:14px;background:#fff}.accessory-search-box:focus-within{border-color:var(--blue);box-shadow:0 0 0 4px rgba(11,92,255,.09)}.accessory-search-box span{font-size:20px}.accessory-search-box input{width:100%;border:0;outline:0;padding:15px 0;font-size:16px;background:transparent}.accessory-search-count{padding:0 24px 10px;color:var(--muted);font-size:13px}.accessory-search-results{overflow:auto;padding:4px 24px 24px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.accessory-search-card{display:grid;grid-template-columns:150px 1fr;gap:16px;border:1px solid var(--line);border-radius:17px;padding:13px;background:#fff;box-shadow:0 7px 20px rgba(10,28,52,.06);min-height:178px}.accessory-search-photo{height:150px;border-radius:13px;background:#f5f7fa;display:flex;align-items:center;justify-content:center;overflow:hidden}.accessory-search-photo img{width:100%;height:100%;object-fit:contain}.accessory-search-noimage{font-size:40px}.accessory-search-info{min-width:0;display:flex;flex-direction:column;align-items:flex-start}.accessory-search-brand{min-height:18px;color:var(--blue);font-size:12px;font-weight:700;text-transform:uppercase}.accessory-search-info h3{margin:3px 0 5px;font-size:15px;line-height:1.25}.accessory-search-info small{color:var(--muted);font-size:11px}.accessory-search-info strong{margin:10px 0;font-size:17px}.accessory-add-button{margin-top:auto;width:100%;font-size:13px;padding:10px 12px}.accessory-search-empty{grid-column:1/-1;text-align:center;padding:50px 20px;color:var(--muted)}.accessory-search-empty span{display:block;font-size:40px;margin-bottom:10px}.accessory-search-empty b,.accessory-search-empty small{display:block}.accessory-search-empty b{color:var(--ink);margin-bottom:5px}@media(max-width:760px){.accessory-search-launcher{align-items:flex-start;flex-direction:column;gap:5px}.accessory-modal{padding:8px}.accessory-modal-dialog{max-height:94vh;border-radius:18px}.accessory-modal-head{padding:18px 16px 12px}.accessory-search-box{margin:12px 16px 8px}.accessory-search-count{padding-left:16px;padding-right:16px}.accessory-search-results{padding:4px 16px 18px;grid-template-columns:1fr}.accessory-search-card{grid-template-columns:120px 1fr;min-height:145px}.accessory-search-photo{height:120px}.accessory-search-info h3{font-size:14px}.accessory-add-button{font-size:12px;padding:9px 8px}}\nbody.accessory-modal-open{overflow:hidden}\n'''
idx.write_text(I,encoding='utf-8');app.write_text(A,encoding='utf-8');css.write_text(C,encoding='utf-8')
print('OK: pesquisa de acessórios instalada em www/index.html, www/app.js e www/style.css.')
